<div class="page-header"><div><span class="staff-eyebrow">Access control</span><h2>Roles & Permissions</h2><p>Create roles such as Website Editor or Project Manager, then assign them to staff.</p></div><a class="btn btn-primary" href="<?=htmlspecialchars(url('/admin/roles/create'))?>"><i data-lucide="shield-plus"></i> Create Role</a></div>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Role</th><th>Description</th><th>Module Access</th><th>Staff</th><th>Actions</th></tr></thead><tbody><?php foreach($roles as$role):$permissions=json_decode((string)$role['permissions'],true)?:[];?><tr><td><strong><?=htmlspecialchars($role['name'])?></strong><small class="table-subtext"><?=htmlspecialchars($role['slug'])?><?=$role['is_system']?' · System':''?></small></td><td><?=htmlspecialchars($role['description']?:'—')?></td><td><div class="staff-skills"><?php foreach($permissions as$module=>$actions):?><span><?=htmlspecialchars(ucwords(str_replace('_',' ',$module)))?> · <?=in_array('manage',$actions,true)?'Manage':'View'?></span><?php endforeach?></div></td><td><?=number_format((int)$role['users_count'])?></td><td><div class="row-actions"><a class="btn btn-sm" href="<?=htmlspecialchars(url('/admin/roles/'.$role['id'].'/edit'))?>">Edit</a><?php if(!$role['is_system']):?><form method="post" action="<?=htmlspecialchars(url('/admin/roles/'.$role['id'].'/delete'))?>" onsubmit="return confirm('Delete this role?')"><?=csrf_field()?><button class="btn btn-sm btn-danger">Delete</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></div>
